// Build Supabase PostgREST query from search parameters
const input = $input.first().json.body || $input.first().json;

const category = (input.category || '').trim().toLowerCase();
const minPrice = parseFloat(input.min_price) || 0;
const maxPrice = parseFloat(input.max_price) || 999999;
const size = (input.size || '').trim().toUpperCase();
const colour = (input.colour || '').trim().toLowerCase();
const gender = (input.gender || '').trim().toLowerCase();
const keyword = (input.keyword || '').trim().toLowerCase();
const limit = Math.min(parseInt(input.limit) || 10, 20);

// Build PostgREST query params for the products table
// We query products with a select that embeds product_variants
let queryParts = [];
queryParts.push('is_active=eq.true');

if (category) {
  queryParts.push(`category=eq.${encodeURIComponent(category)}`);
}
if (gender && ['men', 'women', 'unisex', 'kids'].includes(gender)) {
  queryParts.push(`gender=in.(${encodeURIComponent(gender)},unisex)`);
}
if (keyword) {
  queryParts.push(`or=(name.ilike.*${encodeURIComponent(keyword)}*,description.ilike.*${encodeURIComponent(keyword)}*,tags.cs.{${encodeURIComponent(keyword)}})`);
}

// Price filter: use effective price (sale_price if set, else base_price)
if (minPrice > 0) {
  queryParts.push(`or=(and(sale_price.not.is.null,sale_price.gte.${minPrice}),and(sale_price.is.null,base_price.gte.${minPrice}))`);
}
if (maxPrice < 999999) {
  queryParts.push(`or=(and(sale_price.not.is.null,sale_price.lte.${maxPrice}),and(sale_price.is.null,base_price.lte.${maxPrice}))`);
}

// Select with embedded variants
const selectFields = 'id,sku,name,description,category,brand,gender,base_price,sale_price,currency,image_urls,tags,product_variants!inner(id,size,colour,sku,available_quantity,reserved_quantity,is_active)';

let queryString = queryParts.join('&');

return [{
  json: {
    queryString,
    selectFields,
    limit,
    filterSize: size,
    filterColour: colour,
    filterMinPrice: minPrice,
    filterMaxPrice: maxPrice
  }
}];

// Filter, group, and format product results
const response = $input.first().json;
const products = response.body || response;
const prev = $('Build Query').first().json;
const filterSize = prev.filterSize;
const filterColour = prev.filterColour;
const limit = prev.limit || 10;

if (!Array.isArray(products) || products.length === 0) {
  return [{ json: { products: [], total: 0, message: 'No products found matching your criteria.' } }];
}

const formatted = [];

for (const product of products) {
  let variants = (product.product_variants || []).filter(v => v.is_active);

  // Filter by size if specified
  if (filterSize) {
    variants = variants.filter(v => v.size.toUpperCase() === filterSize);
  }
  // Filter by colour if specified
  if (filterColour) {
    variants = variants.filter(v => v.colour.toLowerCase() === filterColour.toLowerCase());
  }
  // Only include variants with available stock
  variants = variants.filter(v => (v.available_quantity - v.reserved_quantity) > 0);

  if (variants.length === 0) continue;

  const effectivePrice = product.sale_price || product.base_price;
  const isOnSale = product.sale_price !== null && product.sale_price < product.base_price;

  const sizes = [...new Set(variants.map(v => v.size))];
  const colours = [...new Set(variants.map(v => v.colour))];
  const totalStock = variants.reduce((sum, v) => sum + (v.available_quantity - v.reserved_quantity), 0);

  formatted.push({
    product_id: product.id,
    sku: product.sku,
    name: product.name,
    description: product.description,
    category: product.category,
    brand: product.brand,
    gender: product.gender,
    price: effectivePrice,
    original_price: isOnSale ? product.base_price : null,
    is_on_sale: isOnSale,
    currency: product.currency || 'LKR',
    available_sizes: sizes,
    available_colours: colours,
    total_stock: totalStock,
    image_url: (product.image_urls && product.image_urls.length > 0) ? product.image_urls[0] : null,
    variants: variants.map(v => ({
      variant_id: v.id,
      size: v.size,
      colour: v.colour,
      sku: v.sku,
      stock: v.available_quantity - v.reserved_quantity
    }))
  });
}

// Sort by relevance: on-sale items first, then by price ascending
formatted.sort((a, b) => {
  if (a.is_on_sale && !b.is_on_sale) return -1;
  if (!a.is_on_sale && b.is_on_sale) return 1;
  return a.price - b.price;
});

const results = formatted.slice(0, limit);

return [{
  json: {
    products: results,
    total: results.length,
    message: results.length > 0
      ? `Found ${results.length} product(s) matching your criteria.`
      : 'No products found matching your criteria.'
  }
}];

// Build the final response for the AI tool call
const data = $input.first().json;

const responseBody = {
  success: true,
  data: {
    products: data.products,
    total_results: data.total,
    message: data.message
  }
};

return [{ json: responseBody }];
